const MENU_REJECT_EXACT_V3 = ["양파라멘","닭고기라멘","소고기라멘","돼지고기라멘","감자라멘","당근라멘","무라멘","양파우동","감자우동","소고기짬뽕","닭고기짬뽕","무갈비찜","감자파스타","양파파스타","대파파스타","닭고기파스타"];
const MENU_REJECT_PATTERNS_V3 = [
  /^(양파|감자|당근|무|대파|마늘|소고기|돼지고기|닭고기)(라멘|우동|파스타)$/,
  /^(소고기|닭고기|돼지고기)짬뽕$/,
  /^무갈비찜$/
];
function isRejectedMenuNameV3(name){
  const q=String(name||'').replace(/\s/g,'').trim();
  return MENU_REJECT_EXACT_V3.some(x=>x.replace(/\s/g,'')===q)||MENU_REJECT_PATTERNS_V3.some(rx=>rx.test(q));
}
function menuGroupOfV3(name){
  const n=flowMenuDBName?flowMenuDBName(name):name;
  for(const [gid,g] of Object.entries(MENU_GROUP_DB_V3)){
    if(g.name===n||g.variations.includes(n)) return g;
  }
  return null;
}

function v2NormText(x){return String(x||'').toLowerCase().replace(/[\s·.,()\[\]{}]/g,'').trim();}
const ING_ALIAS_INDEX_V2 = (()=>{
  const idx={};
  Object.values(INGREDIENT_DB_V2).forEach(i=>{
    [i.name,i.id].concat(i.aliases||[]).forEach(a=>{idx[v2NormText(a)]=i.id;});
  });
  return idx;
})();
function ingredientIdOf(name){
  const n=v2NormText(name);
  if(!n)return null;
  if(ING_ALIAS_INDEX_V2[n])return ING_ALIAS_INDEX_V2[n];
  for(const [alias,id] of Object.entries(ING_ALIAS_INDEX_V2)){
    if(alias && (n.includes(alias)||alias.includes(n))) return id;
  }
  return null;
}
function ingredientNameOf(id){return INGREDIENT_DB_V2[id]?.name || id;}
function ingredientObjOf(id){
  const i=INGREDIENT_DB_V2[id] || {id,name:id,category:'other',icon:getIcon(id),defaultAmount:'적당량',aliases:[]};
  const catMap={grain:'면·밥',protein:'단백질',dairy:'단백질',veg:'채소',fruit:'채소',sauce:'양념',spice:'양념',nut:'기타',other:'기타'};
  return {id:i.id,name:i.name,amount:i.defaultAmount||'적당량',icon:i.icon||getIcon(i.name),category:catMap[i.category]||'기타'};
}

function inferRecipeServingsV3(menu){
  const name = String(menu?.name || '');
  const ids = menu?.ingredients || [];
  const styles = menu?.styles || [menu?.style || ''];
  const has = (...words) => words.some(w => name.includes(w));

  // 대용량/나눠먹는 한식류
  if(has('감자탕','갈비탕','삼계탕','백숙','곰탕','설렁탕','육개장','부대찌개','해물탕','매운탕','샤브샤브','전골')) return 4;
  if(has('돼지갈비찜','소갈비찜','갈비찜','찜닭','닭볶음탕','김치찜','수육','보쌈','족발','잡채')) return 4;
  if(has('김치찌개','된장찌개','차돌된장찌개','순두부찌개','청국장찌개','고추장찌개','동태찌개','참치김치찌개','돼지고기김치찌개')) return 3;
  if(has('카레','하이라이스','짜장','마파두부','라따뚜이','라자냐','무사카')) return 3;

  // 볶음/조림/구이 반찬형은 보통 2인분으로 잡는다.
  if(has('제육볶음','돼지불고기','소불고기','오징어볶음','낙지볶음','쭈꾸미볶음','어묵볶음','감자볶음','멸치볶음','두부조림','고등어조림','갈치조림','코다리조림','장조림')) return 2;
  if(has('닭갈비','오리불고기','탕수육','깐풍기','유린기','깐쇼새우','칠리새우','난자완스','동파육')) return 3;

  // 1인분 완성형: 밥/면/샐러드/토스트/덮밥/파스타/라멘/우동 등
  if(has('덮밥','비빔밥','볶음밥','국수','라면','라멘','우동','소바','냉면','쌀국수','파스타','리조또','오믈렛','토스트','샌드위치','포케','샐러드','오트밀','랩','타코','부리토','퀘사디야')) return 1;
  if(styles.some(s => ['헬시','일식'].includes(s)) && ids.some(id => ['spaghetti','ramen','udon','soba','rice_noodle','bread','tortilla','oatmeal'].includes(id))) return 1;

  // 기본값: 국/찌개/공유요리는 2인분 이상인 경우가 많아 2로 둔다.
  return 2;
}


function normalizeRecipeServingsV4(m){
  const name=String(m?.name||'');
  const ids=m?.ingredients||[];
  const amts=m?.ingredientAmounts||{};
  const num=(id)=>{const v=String(amts[id]||''); const n=parseFloat(v); return Number.isFinite(n)?n:0;};
  const explicit=Math.max(1, Number(m?.servings||m?.recipeServings||0));
  const override={
    '치킨아도보':2,'시니강':2,'똠얌꿍':2,'똠카가이':2,'바쿠테':2,'락사':2,'분보후에':2,
    '렌당':4,'하이난치킨라이스':2,'칠리크랩':2,'사테아얌':2,'가도가도':2,
    '버터치킨커리':3,'치킨티카마살라':3,'팔락파니르':3,'차나마살라':3,'비리야니':3,'탄두리치킨':2
  };
  if(override[name]) return override[name];
  const liquidMl=['water','broth','anchovy_broth','chicken_broth','vegetable_broth','beef_stock','coconut_milk'].reduce((sum,id)=>sum+num(id),0);
  const proteinG=['chicken','pork','beef','shrimp','fish','salmon','duck','lamb'].reduce((sum,id)=>sum+num(id),0);
  const multiDish=/찌개|탕|국|전골|수프|스튜|찜|조림|탕|나베|커리|카레|시니강|똠|락사|바쿠테|렌당|아도보/.test(name);
  if(liquidMl>=500 && multiDish) return Math.max(explicit,2);
  if(proteinG>=280 && multiDish) return Math.max(explicit,2);
  return explicit||1;
}

function buildMenuDBV2(){
  const next={};
  Object.values(MENU_SCHEMA_V2).forEach(m=>{
    const ids=[...new Set((m.ingredients||[]).map(id=>INGREDIENT_DB_V2[id]?id:null).filter(Boolean))];
    if(!ids.length)return;
    next[m.name]={
      id:m.id||v2NormText(m.name), name:m.name, style:m.styles?.[0]||m.style||'기타', styles:m.styles||[m.style||'기타'], ingredientIds:ids,
      ingredients:ids.map(id=>({...ingredientObjOf(id), amount:(m.ingredientAmounts&&m.ingredientAmounts[id])||ingredientObjOf(id).amount})), cookTime:m.cookTime||getCookTime(m.name), servings:normalizeRecipeServingsV4(m), recipeServings:normalizeRecipeServingsV4(m), ingredientAmounts:m.ingredientAmounts||{}, tags:m.tags||[]
    };
  });
  // ── CLEAN_MENUS도 next에 병합 ──
  var _CLEAN_MENUS = (typeof window.CLEAN_MENUS!=='undefined'&&Array.isArray(window.CLEAN_MENUS)) ? window.CLEAN_MENUS : (typeof CLEAN_MENUS!=='undefined'&&Array.isArray(CLEAN_MENUS)) ? CLEAN_MENUS : [];
  if(_CLEAN_MENUS.length>0){
    _CLEAN_MENUS.forEach(function(m){
      if(next[m.name]) return; // 이미 있으면 MENU_SCHEMA_V2 우선
      const n=m.name;
      const bigPot=/(감자탕|갈비탕|설렁탕|곰탕$|전골$|곰국|꼬리탕|갈비찜$|등갈비찜$|부르기뇽|코코뱅|굴라쉬|오소부코|아이리시스튜|페이조아다|하리라)/.test(n);
      const side=/(나물$|무침$|장아찌$|절임$|깍두기$|김치$)/.test(n);
      const multi=/(잡곡밥|비빔밥$|수프카레|카레라이스)/.test(n);
      const sv=bigPot?4:side?4:multi?3:2;
      const ings=(m.ingredients||[]).map(function(ing){
        const ingName = typeof ing === 'string' ? ing : (ing.name || '');
        const stdData = (typeof STD_ING !== 'undefined' && STD_ING[ingName]) ? STD_ING[ingName] : null;
        if(stdData) return {name:ingName, amount:stdData[0], icon:stdData[1], category:stdData[2]};
        if(typeof ingObj==='function') return ingObj(ingName);
        return {name:ingName, amount:'100g', icon:'🥬', category:'기타'};
      });
      // 헬시 태그 있으면 styles에 헬시도 포함
      const mStyles=[m.style||'기타'];
      if((m.tags||[]).includes('헬시')&&!mStyles.includes('헬시')) mStyles.push('헬시');
      const isSideType = m.type === 'side';
      next[n]={
        id:n, name:n, style:m.style||'기타', styles:mStyles,
        ingredients:ings, cookTime:m.cookTime||20,
        servings:sv, recipeServings:sv,
        tags:m.tags||[], ingredientAmounts:{},
        mealRole: isSideType ? 'side' : 'main',
        excludeFromMainPlan: isSideType,
        category: isSideType ? '반찬' : undefined
      };
    });
  }

  // ===== MENU QUALITY AUDIT v4: remove/rename mistranslated generated menu names =====
  const MENU_QUALITY_RENAME_V4 = {
    '오징어먹물 파스타':'오징어먹물 파스타','굴라쉬':'굴라쉬','헝가리굴라쉬':'굴라쉬','독일굴라쉬':'굴라쉬',
    '닭한마리국물면':'닭칼국수','된장고추찌개':'고추장찌개','사케미소수프':'연어 미소국','하이난 치킨라이스':'하이난 치킨라이스',
    '비프 렌당':'비프 렌당','슬로피조':'슬로피 조','뉴올리언스잠발라야':'잠발라야','세비체클라시코':'클래식 세비체'
  };
  const MENU_QUALITY_BAD_RE_V4 = /(갈치속젓찌개|된장고추찌개|닭한마리국물면|국물면|속젓찌개|볼로네제 폴란드|소금 피시 아크리|불르구르|키나웅카우|비나쿠완|망가버섯볶음|쉑쉬야락타마투|지코에|오크라밥자메|에고나치킨|할랜드소이야|크룹카코르|차조미스타드|얌싸워이|삼발레박|수코드폴로|예도로인제라|피카디요 콜롬비아|바이삿 튀니지|대만 닭껍질|피타야 치킨|자메이카 피시티|피리 피리 치킨 나이지리아)/;
  Object.keys(next).forEach(function(oldName){
    if(MENU_QUALITY_BAD_RE_V4.test(oldName)){ delete next[oldName]; return; }
    const newName = MENU_QUALITY_RENAME_V4[oldName];
    if(newName && newName !== oldName){
      if(!next[newName]){ next[newName] = Object.assign({}, next[oldName], {id:newName, name:newName}); }
      delete next[oldName];
    }
  });

  Object.keys(MENU_DB).forEach(k=>delete MENU_DB[k]);
  Object.assign(MENU_DB,next);
  window.INGREDIENT_DB=INGREDIENT_DB_V2;
  window.MENU_SCHEMA=MENU_SCHEMA_V2;
  const styleMap={};
  Object.values(next).forEach(m=>{(m.styles||[m.style]).forEach(s=>{if(!styleMap[s])styleMap[s]=[];styleMap[s].push(m.name);});});
  if(typeof FLOW_STYLE_MENU_MAP==='object'){
    Object.keys(FLOW_STYLE_MENU_MAP).forEach(k=>delete FLOW_STYLE_MENU_MAP[k]);
    Object.assign(FLOW_STYLE_MENU_MAP,styleMap);
    
  }
  console.info('[Homekeeper DB v3 recipe-audited]',Object.keys(INGREDIENT_DB_V2).length+' ingredients',Object.keys(MENU_DB).length+' menus','대표 메뉴 DB / 조합 생성 메뉴 제거');
}
buildMenuDBV2();
function fridgeIngredientIdsV2(){
  return [...new Set((S.fridge||[]).map(f=>ingredientIdOf(f.name||f.replaceName||'')).filter(Boolean))];
}
function flowHasIng(ingName,fridgeNames){
  const id=ingredientIdOf(ingName)||ingName;
  return fridgeIngredientIdsV2().includes(id) || (fridgeNames||[]).some(f=>String(f).includes(ingName)||String(ingName).includes(f));
}
function getIngredientsFromDB(menus, people){
  const merged={};
  let allFound=true;
  const fridgeNames=S.fridge.map(f=>(f.name||'').trim());
  const fridgeIds=fridgeIngredientIdsV2();
  for(const menu of menus||[]){
    const name=flowMenuDBName(menu);
    const db=MENU_DB[name];
    if(!db){allFound=false;continue;}
    for(const ingItem of (db.ingredients||[])){
      // id 있으면 V2 방식, 없으면 name 기반 fallback
      const id=ingItem.id||null;
      const ingName=ingItem.name||ingredientNameOf(id)||'';
      if(!ingName) continue;
      const key=id||ingName;
      // STD_ING에서 amount 직접 참조 (ingObj 변환이 실패했을 경우 대비)
      let amount = ingItem.amount;
      if(!amount || amount === '적당량') {
        const stdData = (typeof STD_ING !== 'undefined' && STD_ING[ingName]);
        amount = stdData ? stdData[0] : '100g';
      }
      const icon=ingItem.icon||getIcon(ingName);
      const category=ingItem.category||'기타';
      const inFridge=id?fridgeIds.includes(id):fridgeNames.some(f=>f.includes(ingName)||ingName.includes(f));
      if(!merged[key]){
        merged[key]={name:ingName, id:key, amount, icon, category, inFridge, usedIn:name};
      } else {
        // 같은 재료 여러 메뉴에 쓰일 때 합산
        const ex=parseFloat(merged[key].amount)||0;
        const cur=parseFloat(amount)||0;
        const unit=(amount||'').replace(/[0-9.]/g,'').trim();
        if(ex&&cur) merged[key].amount=Math.round((ex+cur)*people*10)/10+unit;
        merged[key].inFridge=merged[key].inFridge||inFridge;
        if(!String(merged[key].usedIn||'').includes(name))
          merged[key].usedIn=(merged[key].usedIn?merged[key].usedIn+', ':'')+name;
      }
    }
  }
  return {list:Object.values(merged), allFound};
}
function flowScoreMenuByFridge(name){
  const db=MENU_DB[name]; if(!db)return -999;
  const have=new Set(fridgeIngredientIdsV2());
  const ids=db.ingredientIds||[];
  const core=ids.filter(id=>['protein','veg','grain','dairy'].includes(INGREDIENT_DB_V2[id]?.category));
  const haveCount=ids.filter(id=>have.has(id)).length;
  const coreHave=core.filter(id=>have.has(id)).length;
  const missing=Math.max(0,ids.length-haveCount);
  const expiryBoost=(S.fridge||[]).reduce((sum,f)=>{
    const id=ingredientIdOf(f.name); const d=getDday(f.addedAt,f.expireDays);
    return sum+(id&&ids.includes(id)&&d<=3?4:0);
  },0);
  return haveCount*4+coreHave*6+expiryBoost-missing*0.7+getSeasonalScore(name)*1.5-Math.random();
}
function flowMealObj(type,name){
  const db=MENU_DB[name];
  return {type,name,mainIngredients:db?(db.ingredientIds||[]).slice(0,4).map(ingredientNameOf):[],cookTime:db?.cookTime||getCookTime(name),nutrition:{protein:'중간',carb:'중간',veggie:'있음'},sides:getSides(name,type)};
}
function resolveMenu(name){
  if(!name)return null;
  if(MENU_DB[name])return name;
  const q=String(name).trim();
  const exact=Object.keys(MENU_DB).find(k=>k.replace(/\s/g,'')===q.replace(/\s/g,''));
  if(exact)return exact;
  const partial=Object.keys(MENU_DB).find(k=>k.includes(q)||q.includes(k));
  if(partial)return partial;
  return null;
}
function flowMenuDBName(name){return resolveMenu(name)||name;}
function findSimilarMenus(selected,exclude=[]){
  const ex=new Set((exclude||[]).map(flowMenuDBName));
  const seed=(selected||[]).map(flowMenuDBName).filter(n=>MENU_DB[n]);
  const wantedStyles=[...new Set(seed.flatMap(n=>MENU_DB[n].styles||[MENU_DB[n].style]))];
  const wantedIds=[...new Set(seed.flatMap(n=>MENU_DB[n].ingredientIds||[]))];
  return Object.keys(MENU_DB).filter(n=>!ex.has(n)).map(n=>{
    const m=MENU_DB[n];
    const styleScore=(m.styles||[m.style]).some(s=>wantedStyles.includes(s))?5:0;
    const ingScore=(m.ingredientIds||[]).filter(id=>wantedIds.includes(id)).length;
    return {n,score:styleScore+ingScore};
  }).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.n).slice(0,80);
}
